from jsonb_to_recordset($q$[{"id":3539,"materia":"ling","nivel":0,"enunciado":"Em uma conversa entre amigos, o uso de gírias é exemplo de variação linguística:","opcoes":["Adequada à situação informal","Sempre errada em qualquer contexto","Proibida pela norma-padrão","Restrita à escrita formal"],"explicacao":"A adequação depende do contexto; gírias cabem em situações informais."},{"id":3540,"materia":"ling","nivel":0,"enunciado":"Um texto cujo principal objetivo é convencer o leitor a comprar um produto tem função:","opcoes":["Apelativa (conativa)","Referencial","Metalinguística","Fática, que mantém o canal aberto"],"explicacao":"A função apelativa busca influenciar o comportamento do interlocutor."},{"id":3541,"materia":"ling","nivel":0,"enunciado":"Charges e tirinhas costumam combinar:","opcoes":["Linguagem verbal e não verbal","Apenas números e gráficos","Somente textos científicos","Apenas sons e músicas"],"explicacao":"Texto e imagem constroem juntos o sentido."},{"id":3542,"materia":"ling","nivel":0,"enunciado":"Dizer 'Ela tem um coração de pedra' é usar uma:","opcoes":["Metáfora","Hipérbole","Onomatopeia","Antítese"],"explicacao":"Comparação implícita: o coração é 'duro' como pedra."},{"id":3543,"materia":"ling","nivel":0,"enunciado":"O gênero textual que relata fatos recentes de forma objetiva, publicado em jornais, é a:","opcoes":["Notícia","Crônica","Fábula","Poesia"],"explicacao":"A crônica mistura fato e opinião em tom leve."},{"id":3544,"materia":"ling","nivel":1,"enunciado":"Quando um texto fala sobre a própria linguagem, como um verbete de dicionário, predomina a função:","opcoes":["Metalinguística","Emotiva","Poética","Apelativa"],"explicacao":"A linguagem explica a própria linguagem."},{"id":3545,"materia":"ling","nivel":1,"enunciado":"'Alô? Está me ouvindo?' é exemplo de função da linguagem:","opcoes":["Fática","Referencial","Poética","Metalinguística"],"explicacao":"Serve para testar ou manter o canal de comunicação."},{"id":3546,"materia":"ling","nivel":1,"enunciado":"O Modernismo brasileiro teve como marco inicial a:","opcoes":["Semana de Arte Moderna de 1922","Fundação da Academia Brasileira de Letras","Publicação de Os Lusíadas","Proclamação da República"],"explicacao":"Rompeu com padrões acadêmicos e valorizou a identidade nacional."},{"id":3547,"materia":"ling","nivel":1,"enunciado":"Intertextualidade ocorre quando um texto:","opcoes":["Retoma ou dialoga com outro texto","Usa apenas palavras estrangeiras e termos técnicos","Não tem título","É escrito em versos livres"],"explicacao":"Ex.: paródias e paráfrases de poemas conhecidos."},{"id":3548,"materia":"ling","nivel":2,"enunciado":"A paródia se diferencia da paráfrase porque:","opcoes":["Subverte o sentido do texto original, muitas vezes com humor ou crítica","Mantém fielmente o sentido do texto original","Traduz o texto para outra língua","Resume o texto em poucas linhas"],"explicacao":"A paráfrase reafirma o sentido com outras palavras."},{"id":3549,"materia":"ling","nivel":2,"enunciado":"O Romantismo brasileiro, em sua primeira geração, valorizou especialmente:","opcoes":["O nacionalismo e a figura do indígena idealizado","A crítica social e o determinismo","A arte pela arte e a forma perfeita","O fluxo de consciência e a linguagem coloquial urbana"],"explicacao":"Ex.: Gonçalves Dias e José de Alencar."},{"id":3550,"materia":"ling","nivel":3,"enunciado":"O Realismo de Machado de Assis se destaca por:","opcoes":["Ironia e análise psicológica das personagens","Exaltação da natureza e do herói nacional","Linguagem rebuscada sem crítica social","Rejeição de qualquer narrador em primeira pessoa"],"explicacao":"Ex.: Memórias Póstumas de Brás Cubas e Dom Casmurro."},{"id":3551,"materia":"ling","nivel":3,"enunciado":"No Naturalismo, as personagens costumam ser explicadas pelo:","opcoes":["Determinismo do meio, da raça e do momento histórico","Livre-arbítrio absoluto","Destino traçado pelos deuses","Amor idealizado e a fuga para a natureza"],"explicacao":"Ex.: O Cortiço, de Aluísio Azevedo."},{"id":3552,"materia":"ling","nivel":4,"enunciado":"Em 'O mar serenou quando ela pisou na areia', o recurso que atribui ação humana ao mar é a:","opcoes":["Prosopopeia (personificação)","Metonímia","Catacrese","Elipse"],"explicacao":"Serenar é atribuído ao mar como se fosse um ser animado."},{"id":3553,"materia":"mat","nivel":0,"enunciado":"Uma camiseta de R$ 40,00 está com 10% de desconto. O desconto é de:","opcoes":["R$ 4,00","R$ 10,00","R$ 36,00","R$ 0,40"],"explicacao":"10% de 40 = 4. O preço final fica R$ 36,00."},{"id":3554,"materia":"mat","nivel":0,"enunciado":"A área de um retângulo de 5 m por 3 m é:","opcoes":["15 m²","8 m²","16 m²","30 m²"],"explicacao":"Área = base × altura."},{"id":3555,"materia":"mat","nivel":0,"enunciado":"Se 1 kg de arroz custa R$ 6,00, 3,5 kg custam:","opcoes":["R$ 21,00","R$ 18,00","R$ 24,00","R$ 19,50"],"explicacao":"6 × 3,5 = 21."},{"id":3556,"materia":"mat","nivel":0,"enunciado":"Em uma escala de 1:100, 1 cm no desenho corresponde a:","opcoes":["1 m no real","10 cm no real","100 m no real","1 km no real"],"explicacao":"100 cm = 1 m."},{"id":3557,"materia":"mat","nivel":1,"enunciado":"A mediana do conjunto 1, 4, 9, 10, 20 é:","opcoes":["9","10","8,8","4"],"explicacao":"Com os dados em ordem, é o valor central."},{"id":3558,"materia":"mat","nivel":1,"enunciado":"Ao lançar um dado comum, a probabilidade de sair um número par é:","opcoes":["1/2","1/3","1/6","2/3"],"explicacao":"3 casos favoráveis (2, 4, 6) em 6 possíveis."},{"id":3559,"materia":"mat","nivel":1,"enunciado":"O volume de um cubo de aresta 3 cm é:","opcoes":["27 cm³","9 cm³","18 cm³","81 cm³"],"explicacao":"Volume = aresta³."},{"id":3560,"materia":"mat","nivel":2,"enunciado":"Uma escada de 5 m está apoiada em um muro, com o pé a 3 m da base do muro. A altura alcançada no muro é:","opcoes":["4 m","2 m","3,5 m","8 m"],"explicacao":"Teorema de Pitágoras: 5² = 3² + h², logo h = 4."},{"id":3561,"materia":"mat","nivel":2,"enunciado":"Na função f(x) = 2x + 3, o valor de f(5) é:","opcoes":["13","10","16","8"],"explicacao":"2 × 5 + 3 = 13."},{"id":3562,"materia":"mat","nivel":3,"enunciado":"Um reservatório perde 10% da água a cada dia, em relação ao dia anterior. Depois de 2 dias, resta, do volume inicial:","opcoes":["81%","80%","90%","79%"],"explicacao":"0,9 × 0,9 = 0,81."},{"id":3563,"materia":"mat","nivel":4,"enunciado":"A probabilidade de, em dois lançamentos de uma moeda honesta, sair pelo menos uma cara é:","opcoes":["3/4","1/2","1/4","2/3"],"explicacao":"1 − P(duas coroas) = 1 − 1/4."},{"id":3564,"materia":"mat","nivel":4,"enunciado":"Um mapa tem escala 1:50.000. Uma distância real de 4 km aparece no mapa com:","opcoes":["8 cm","80 cm","2 cm","0,8 cm"],"explicacao":"4 km = 400.000 cm; 400.000 / 50.000 = 8 cm."},{"id":3565,"materia":"fis","nivel":0,"enunciado":"A unidade de medida de força no Sistema Internacional é o:","opcoes":["Newton","Joule","Watt","Pascal"],"explicacao":"Joule mede energia; watt, potência; pascal, pressão."},{"id":3566,"materia":"fis","nivel":0,"enunciado":"Um carro percorre 120 km em 2 horas. Sua velocidade média é:","opcoes":["60 km/h","120 km/h","240 km/h","30 km/h"],"explicacao":"v = distância / tempo."},{"id":3567,"materia":"fis","nivel":0,"enunciado":"O som não se propaga no:","opcoes":["Vácuo","Ar","Água","Metal"],"explicacao":"O som precisa de um meio material."},{"id":3568,"materia":"fis","nivel":1,"enunciado":"A energia que um corpo possui por estar em movimento é a energia:","opcoes":["Cinética","Potencial gravitacional","Elástica","Química"],"explicacao":"Ec = m·v²/2."},{"id":3569,"materia":"fis","nivel":1,"enunciado":"Pela primeira lei de Newton (inércia), um corpo sem força resultante:","opcoes":["Permanece em repouso ou em movimento retilíneo uniforme","Sempre para","Acelera continuamente","Muda de direção a cada instante, em movimento circular"],"explicacao":"A força resultante nula não altera o estado de movimento."},{"id":3570,"materia":"fis","nivel":2,"enunciado":"A potência elétrica de um aparelho ligado em 220 V com corrente de 5 A é:","opcoes":["1.100 W","44 W","225 W","215 W"],"explicacao":"P = U · i."},{"id":3571,"materia":"fis","nivel":2,"enunciado":"Em uma usina hidrelétrica, a principal transformação de energia é de:","opcoes":["Potencial gravitacional em elétrica","Química em nuclear","Térmica em luminosa","Elétrica em química, como numa bateria"],"explicacao":"A queda da água gira as turbinas ligadas aos geradores."},{"id":3572,"materia":"fis","nivel":3,"enunciado":"Um chuveiro de 5.000 W ligado 30 minutos por dia consome, em 30 dias:","opcoes":["75 kWh","150 kWh","2,5 kWh","750 kWh"],"explicacao":"5 kW × 0,5 h × 30 = 75 kWh."},{"id":3573,"materia":"fis","nivel":3,"enunciado":"A refração da luz ocorre quando ela:","opcoes":["Muda de meio e altera sua velocidade","Volta para o mesmo meio após bater em uma superfície","É totalmente absorvida","Se divide em cargas elétricas"],"explicacao":"Ex.: o lápis que parece 'quebrado' dentro do copo d'água."},{"id":3574,"materia":"fis","nivel":4,"enunciado":"Um corpo de 2 kg, em queda livre a partir do repouso, atinge após 3 s a velocidade de (g = 10 m/s²):","opcoes":["30 m/s","20 m/s","60 m/s","15 m/s"],"explicacao":"v = g·t = 10 × 3. A massa não interfere."},{"id":3575,"materia":"qui","nivel":0,"enunciado":"A fórmula química da água é:","opcoes":["H₂O","CO₂","O₂","NaCl"],"explicacao":"Dois átomos de hidrogênio e um de oxigênio."},{"id":3576,"materia":"qui","nivel":0,"enunciado":"A passagem do estado líquido para o gasoso chama-se:","opcoes":["Vaporização","Solidificação","Fusão","Condensação"],"explicacao":"Condensação é o inverso: gasoso para líquido."},{"id":3577,"materia":"qui","nivel":0,"enunciado":"Uma solução com pH 2 é:","opcoes":["Ácida","Básica","Neutra","Salina, sempre"],"explicacao":"pH < 7 é ácido; pH > 7, básico."},{"id":3578,"materia":"qui","nivel":1,"enunciado":"Misturar água e óleo resulta em uma mistura:","opcoes":["Heterogênea","Homogênea","Pura","Azeot