 por:","opcoes":["Maior integração econômica, financeira e de informações entre países","Fechamento das fronteiras comerciais e redução das trocas de informação","Fim do comércio internacional","Isolamento cultural dos países"],"explicacao":"Impulsionada pelas tecnologias de comunicação e transporte."},{"id":3616,"materia":"geo","nivel":2,"enunciado":"A transição demográfica brasileira mostra, nas últimas décadas:","opcoes":["Queda da natalidade e envelhecimento da população","Aumento da natalidade e população mais jovem","Crescimento da mortalidade infantil","Estabilidade total da pirâmide etária"],"explicacao":"A base da pirâmide se estreita."},{"id":3617,"materia":"geo","nivel":3,"enunciado":"O fuso horário de Brasília (UTC−3) está atrasado em relação a Londres (UTC 0) em:","opcoes":["3 horas","2 horas","4 horas","5 horas"],"explicacao":"Quando é meio-dia em Londres, são 9h em Brasília."},{"id":3618,"materia":"geo","nivel":3,"enunciado":"A matriz elétrica brasileira se destaca, em comparação com a média mundial, por:","opcoes":["Grande participação de fontes renováveis, sobretudo hidrelétrica","Dependência quase total do carvão mineral importado de outros países","Predomínio da energia nuclear","Ausência de energia eólica"],"explicacao":"Eólica e solar também cresceram nos últimos anos."},{"id":3619,"materia":"geo","nivel":4,"enunciado":"A conurbação ocorre quando:","opcoes":["Cidades vizinhas crescem até suas malhas urbanas se unirem","A população rural supera a urbana em toda a região metropolitana","Uma cidade perde habitantes","O campo é mecanizado"],"explicacao":"Comum nas regiões metropolitanas."},{"id":3620,"materia":"geo","nivel":4,"enunciado":"O El Niño é o aquecimento anormal das águas do Oceano Pacífico, que no Brasil costuma provocar:","opcoes":["Secas no Nordeste e chuvas acima da média no Sul","Neve na Amazônia","Fim das chuvas no Sul","Terremotos e tsunamis no litoral do Sudeste"],"explicacao":"A La Niña tem efeitos geralmente opostos."},{"id":3621,"materia":"fil","nivel":0,"enunciado":"A frase 'Só sei que nada sei' é atribuída a:","opcoes":["Sócrates","Aristóteles","Descartes","Marx"],"explicacao":"Expressa a consciência da própria ignorância."},{"id":3622,"materia":"fil","nivel":0,"enunciado":"A Sociologia estuda principalmente:","opcoes":["A sociedade e as relações sociais","Os astros e planetas","As rochas e minerais","As reações químicas"],"explicacao":"Surgiu no século XIX com Comte, Durkheim, Weber e Marx."},{"id":3623,"materia":"fil","nivel":0,"enunciado":"'Penso, logo existo' é a frase de:","opcoes":["René Descartes","Platão","Karl Marx","Nietzsche"],"explicacao":"Base do racionalismo moderno."},{"id":3624,"materia":"fil","nivel":1,"enunciado":"Para Karl Marx, a história das sociedades é marcada pela:","opcoes":["Luta de classes","Seleção natural","Vontade divina","Harmonia entre as classes"],"explicacao":"Ex.: burguesia e proletariado."},{"id":3625,"materia":"fil","nivel":1,"enunciado":"Para Émile Durkheim, fato social é algo:","opcoes":["Exterior, geral e coercitivo sobre os indivíduos","Individual e passageiro","Exclusivamente econômico","Biológico e hereditário, transmitido de pais para filhos"],"explicacao":"Ex.: regras, costumes e leis."},{"id":3626,"materia":"fil","nivel":1,"enunciado":"O 'mito da caverna' foi escrito por:","opcoes":["Platão","Aristóteles","Kant","Rousseau"],"explicacao":"Está no livro A República."},{"id":3627,"materia":"fil","nivel":2,"enunciado":"Etnocentrismo é a atitude de:","opcoes":["Julgar outras culturas a partir dos valores da própria cultura","Respeitar todas as culturas igualmente, sem julgá-las pelos próprios valores","Estudar apenas culturas antigas","Defender a mistura de raças"],"explicacao":"O relativismo cultural é a postura oposta."},{"id":3628,"materia":"fil","nivel":2,"enunciado":"Para Rousseau, a sociedade deve se organizar por meio de um:","opcoes":["Contrato social baseado na vontade geral","Governo absoluto de um rei","Estado sem leis","Poder divino da Igreja sobre os governantes"],"explicacao":"Obra: O Contrato Social (1762)."},{"id":3629,"materia":"fil","nivel":3,"enunciado":"Para Thomas Hobbes, sem o Estado, os homens viveriam em:","opcoes":["Guerra de todos contra todos","Harmonia natural","Plena igualdade pacífica e cooperação","Sociedade sem conflitos"],"explicacao":"Por isso defende um soberano forte (o Leviatã)."},{"id":3630,"materia":"fil","nivel":3,"enunciado":"Kant propõe o imperativo categórico, segundo o qual devemos agir:","opcoes":["Como se nossa ação pudesse virar lei universal","Sempre buscando o próprio prazer","Conforme a vontade da maioria","Apenas segundo a tradição"],"explicacao":"Ética do dever."},{"id":3631,"materia":"fil","nivel":4,"enunciado":"O conceito de 'indústria cultural', da Escola de Frankfurt, critica:","opcoes":["A produção da cultura como mercadoria padronizada para o consumo de massa","A preservação das tradições populares","O ensino de filosofia nas escolas","O fim dos meios de comunicação de massa e a volta da cultura oral nas comunidades"],"explicacao":"Termo de Adorno e Horkheimer."},{"id":3632,"materia":"mat","nivel":0,"enunciado":"Um triângulo tem dois ângulos de 50° e 60°. O terceiro ângulo mede:","opcoes":["70°","80°","90°","110°"],"explicacao":"A soma dos ângulos internos de um triângulo é 180°."},{"id":3633,"materia":"mat","nivel":1,"enunciado":"Uma receita usa 3 ovos para 4 pessoas. Para 12 pessoas, são necessários:","opcoes":["9 ovos","12 ovos","6 ovos","16 ovos"],"explicacao":"12 é o triplo de 4; 3 × 3 = 9."},{"id":3634,"materia":"mat","nivel":3,"enunciado":"Uma pizza de 30 cm de diâmetro tem área aproximada de (use π = 3):","opcoes":["675 cm²","900 cm²","90 cm²","2.700 cm²"],"explicacao":"Raio 15 cm: 3 × 15² = 675."},{"id":3635,"materia":"mat","nivel":4,"enunciado":"As vendas de uma loja passaram de 200 em janeiro para 260 em fevereiro. O aumento percentual foi de:","opcoes":["30%","60%","26%","13%"],"explicacao":"Aumento de 60 sobre 200 = 0,30."},{"id":3636,"materia":"mat","nivel":2,"enunciado":"Em uma turma de 30 alunos, 18 são meninas. A porcentagem de meninas é:","opcoes":["60%","18%","40%","50%"],"explicacao":"18 / 30 = 0,6."},{"id":3637,"materia":"his","nivel":1,"enunciado":"O Quilombo dos Palmares, símbolo da resistência à escravidão, teve como líder mais conhecido:","opcoes":["Zumbi","Tiradentes","Dom Pedro II","Duque de Caxias"],"explicacao":"O 20 de novembro, Dia da Consciência Negra, lembra sua morte."},{"id":3638,"materia":"fil","nivel":1,"enunciado":"Para Aristóteles, o ser humano é por natureza um animal:","opcoes":["Político","Solitário","Sem razão","Apenas instintivo"],"explicacao":"Vive na pólis e se realiza na vida em comunidade."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select materia, count(*) as questoes from public.questoes where materia in ('ling','mat','fis','qui','bio','his','geo','fil') group by materia order by materia;
select count(*) as total_de_questoes from public.questoes;
